MODULES = [{'title': '1. Algebra is a Tool, Not a Monster', 'concept': 'Algebra is a way to describe unknown quantities and relationships.', 'analogy': 'Think of a sealed box. You can see what goes in and what comes out, even before you know what is inside.', 'rule': 'A letter such as x is simply a placeholder for a number.', 'ex1': '3 boxes cost ₹150. If each box has the same price, 3x = 150.', 'steps': ['3x = 150', 'x = 150 ÷ 3', 'x = ₹50'], 'ex2': 'If one ticket costs x rupees, five tickets cost 5x.', 'mistake': 'Treating x as a mysterious symbol instead of a number you do not know yet.', 'practice': 'A cricket bat costs x rupees. Two bats and a ₹200 grip cost ₹2200. Write the equation.', 'answer': '2x + 200 = 2200'}, {'title': '2. Variables, Constants and Coefficients', 'concept': 'An algebraic expression has pieces with different jobs: variables can change, constants stay fixed, and coefficients multiply variables.', 'analogy': 'Imagine a jersey order: player count can change, printing setup cost can stay fixed, and price per jersey multiplies the player count.', 'rule': 'In 350x + 500, x is the variable, 350 is the coefficient, and 500 is the constant.', 'ex1': 'For x jerseys at ₹350 each plus ₹500 setup, total = 350x + 500.', 'steps': ['variable: x', 'coefficient: 350', 'constant: 500'], 'ex2': '7y - 12 has variable y, coefficient 7, constant -12.', 'mistake': 'Calling every number a coefficient. A number without a variable is a constant.', 'practice': 'In 40x + 15y + 100, identify variables, coefficients and constant.', 'answer': 'Variables x,y; coefficients 40,15; constant 100.'}, {'title': '3. Build Expressions from Real Situations', 'concept': 'Expressions are compact descriptions of calculations. They do not need an equals sign.', 'analogy': 'A bill is a story converted into arithmetic. Algebra lets one bill formula work for many quantities.', 'rule': 'Translate one phrase at a time: “per item” usually means multiplication; “plus fee” means addition.', 'ex1': 'A taxi charges ₹60 base fare plus ₹14 per kilometre: 60 + 14k.', 'steps': ['base fare → 60', 'per km → 14k', 'combine → 60 + 14k'], 'ex2': 'Three notebooks at p rupees each and a ₹20 pen: 3p + 20.', 'mistake': 'Putting an equals sign into an expression before there is a total value to equal.', 'practice': 'A shop sells x T-shirts at ₹399 each and charges ₹80 delivery. Write the expression.', 'answer': '399x + 80'}, {'title': '4. Like Terms and Simplifying', 'concept': 'Like terms have the same variable part and can be combined.', 'analogy': 'You can combine three apples and five apples, but you cannot call three apples plus five oranges eight apples.', 'rule': 'Add or subtract coefficients only when the variable part matches exactly.', 'ex1': '3x + 5x = 8x.', 'steps': ['same variable x', 'add coefficients 3 + 5', 'result 8x'], 'ex2': '4x + 2y + 3x - y = 7x + y.', 'mistake': 'Combining 2x and 2x²; they are not like terms.', 'practice': 'Simplify 6a + 4b - 2a + 3b.', 'answer': '4a + 7b'}, {'title': '5. Equations are Balances', 'concept': 'An equation says two quantities are equal. Solving means finding the value that keeps both sides balanced.', 'analogy': 'Picture a weighing scale. Whatever operation you do on one side, do the same on the other.', 'rule': 'Use inverse operations to isolate the variable while preserving equality.', 'ex1': 'x + 7 = 19. Subtract 7 from both sides.', 'steps': ['x + 7 = 19', 'x + 7 - 7 = 19 - 7', 'x = 12'], 'ex2': '5x = 45, so x = 9.', 'mistake': 'Moving a term across the equals sign without understanding that you are applying the same operation to both sides.', 'practice': 'Solve 3x + 4 = 25.', 'answer': '3x = 21, so x = 7.'}, {'title': '6. Brackets and the Distributive Property', 'concept': 'A number outside brackets multiplies every term inside the brackets.', 'analogy': 'If three teams each receive two balls and one cone, then every team receives both items.', 'rule': 'a(b + c) = ab + ac.', 'ex1': '3(x + 4) = 3x + 12.', 'steps': ['3 × x = 3x', '3 × 4 = 12', 'result 3x + 12'], 'ex2': '2(5y - 3) = 10y - 6.', 'mistake': 'Multiplying only the first term inside brackets.', 'practice': 'Expand 4(2x + 5).', 'answer': '8x + 20'}, {'title': '7. Fractions, Ratios and Proportion', 'concept': 'Fractions in algebra behave like ordinary fractions; the variable simply stands for a number.', 'analogy': 'A team budget split equally among players is division, even if we do not yet know the exact budget.', 'rule': 'To remove a denominator, multiply both sides by that denominator.', 'ex1': 'x/4 = 6, so x = 24.', 'steps': ['x/4 = 6', 'multiply both sides by 4', 'x = 24'], 'ex2': 'If 3 shirts cost ₹900, one shirt costs 900/3 = ₹300.', 'mistake': 'Multiplying only one side of an equation when clearing a denominator.', 'practice': 'Solve x/5 + 2 = 8.', 'answer': 'x/5 = 6, so x = 30.'}, {'title': '8. Turn Word Problems into Equations', 'concept': 'Word problems become easy when you separate known values, unknown values, and the relationship between them.', 'analogy': 'You are translating from everyday language into mathematical language.', 'rule': 'Choose the unknown first, then build the equation sentence by sentence.', 'ex1': 'After spending ₹250, Ali has ₹750 left. If he started with x, then x - 250 = 750.', 'steps': ['unknown start money → x', 'spent ₹250 → x - 250', 'left ₹750 → x - 250 = 750'], 'ex2': 'A number doubled and increased by 9 gives 31: 2x + 9 = 31.', 'mistake': 'Trying to calculate before deciding what the variable represents.', 'practice': 'Three equal match fees plus ₹500 travel cost total ₹3500. Find each match fee.', 'answer': '3x + 500 = 3500, so x = ₹1000.'}, {'title': '9. Coordinates and Linear Relationships', 'concept': 'A linear relationship connects two variables at a constant rate and can be drawn as a straight line.', 'analogy': 'If each extra jersey always adds the same cost, total cost rises at a constant rate.', 'rule': 'y = mx + b: m is rate of change, b is the starting value.', 'ex1': 'y = 350x + 500 means ₹350 per jersey and ₹500 setup.', 'steps': ['b = 500 → starting cost', 'm = 350 → cost per jersey', 'x → quantity, y → total'], 'ex2': 'For y = 2x + 1, when x = 3, y = 7.', 'mistake': 'Thinking the y-intercept is the rate. The slope m is the rate.', 'practice': 'For y = 40x + 100, what is y when x = 5?', 'answer': 'y = 40×5 + 100 = 300.'}, {'title': '10. Final Challenge: Think Algebraically', 'concept': 'Real algebra is not memorizing steps; it is recognizing structure, representing it, and checking whether the answer makes sense.', 'analogy': 'Like solving a cricket field problem: observe the situation, choose the right tool, execute, then verify.', 'rule': 'Represent → simplify → solve → check.', 'ex1': 'A shop has a ₹150 fixed delivery charge and ₹275 per item. Total is ₹1800. 275x + 150 = 1800.', 'steps': ['275x = 1650', 'x = 6', 'check: 275×6 + 150 = 1800'], 'ex2': '2(x + 5) = 26 → 2x + 10 = 26 → x = 8.', 'mistake': 'Stopping after getting x without substituting it back to check.', 'practice': 'Solve and check: 4(x - 2) + 3 = 27.', 'answer': '4x - 8 + 3 = 27 → 4x = 32 → x = 8.'}]

SCENE_DURATIONS = [57.3, 58.5, 59.6, 52.3, 60.0, 87.3, 59.2, 61.5, 61.5, 50.3, 59.2, 85.4, 57.7, 57.7, 60.4, 53.0, 61.2, 85.8, 56.5, 57.7, 55.7, 51.9, 58.1, 83.1, 58.5, 59.2, 57.3, 54.6, 60.4, 83.8, 56.5, 56.1, 55.0, 53.4, 55.7, 81.5, 57.7, 58.8, 56.1, 52.3, 58.8, 83.8, 58.8, 55.7, 60.8, 55.4, 59.2, 87.7, 59.2, 59.2, 60.0, 55.4, 60.0, 86.5, 59.6, 59.6, 60.0, 52.6, 60.0, 88.5]

KINDS = ['chapter','intuition','rule','steps','compare','practice']
LABELS = ['Module {n}','Feel the idea first','The rule','Watch it happen','One more example','Your turn']

def narration(kind, m):
    if kind == 'chapter':
        return (f"We are starting {m['title']}. {m['concept']} For the next few minutes, do not try to memorize symbols or copy steps. "
                "First understand what the situation means. Then we will convert that meaning into algebra. "
                "A useful habit is to ask three questions: what do I know, what do I not know, and how are those quantities connected? "
                "If you can answer those three questions, most beginner algebra problems become much less scary. "
                "The goal in this module is not speed. The goal is to build a mental picture strong enough that the symbols feel natural. "
                "By the end, you should be able to explain the idea in ordinary language before writing any equation.")
    if kind == 'intuition':
        return (f"Here is the intuition. {m['analogy']} {m['concept']} Notice that the mathematics exists before we write a single symbol. "
                "The symbols only compress the idea. Imagine the situation clearly and say it in your own words. What is changing? What stays fixed? "
                "What is being multiplied, added, divided or compared? When learners get stuck, they often stare at x or y. "
                "Instead, look behind the letter and ask what real quantity it represents. Once that is clear, the algebra is simply a short language for the relationship you already understand. "
                "This is the habit I want you to keep for the entire course.")
    if kind == 'rule':
        return (f"Now we can state the rule: {m['rule']} A rule is useful only when you know why it works, so let us connect it to a real example. {m['ex1']} "
                "Read the expression slowly as a sentence. Point to each piece and explain its job. Ask whether the number is a starting amount, a repeated amount, a rate, a fixed value, or something else. "
                "Do not rush to calculate. In algebra, representation comes before calculation. If the representation is wrong, perfect arithmetic will still give the wrong answer. "
                "If the representation is right, the arithmetic is usually the easy part. So use the rule as a description of structure, not as a magic formula.")
    if kind == 'steps':
        return (f"Watch the steps carefully. We start with {m['steps'][0]}. Then {m['steps'][1]}. Finally {m['steps'][2]}. "
                "Do not just watch the symbols move. Ask what operation happened and why it was allowed. A strong learner should be able to pause after any line and explain the transition to the next line in plain language. "
                "That explanation is more valuable than memorizing a shortcut. Now mentally reverse the steps and check whether the result returns to the original situation. "
                "This backward check is powerful because it catches sign errors, missed terms and careless arithmetic. When you solve your own problems later, copy this rhythm: one small step, one reason, then a quick check.")
    if kind == 'compare':
        return (f"Let us test the idea with another example. {m['ex2']} The numbers look different, but the structure is the same. That is important: algebra is about patterns that survive when the numbers change. "
                f"Now notice a common error: {m['mistake']} Instead of memorizing a warning, understand why the mistake is wrong. Ask what quantity each term represents and whether the proposed operation preserves that meaning. "
                "When you feel unsure, go back to the real situation or substitute a simple number and test it. Meaning and checking are your two fastest error-detection tools. "
                "The more often you compare a correct pattern with a tempting wrong pattern, the faster your mathematical judgment develops.")
    return (f"Your turn. {m['practice']} Do not look at the answer immediately. First say what the unknown represents. Then write one line that connects the known information to that unknown. "
            "Pause the video and give yourself about twenty seconds. If you need a hint, ask which operation the story is describing. "
            f"Now compare your work with this: {m['answer']} If your answer was different, do not simply replace it. Find the exact line where your reasoning changed. "
            "Was the variable defined differently? Did you choose the wrong operation? Did arithmetic cause the error? Fix that exact point and then solve again. That correction is where learning happens. "
            "Finally, explain the answer aloud in one sentence so it connects back to the original situation.")

def make_scenes():
    scenes=[]
    for mi,m in enumerate(MODULES,1):
        for ki,kind in enumerate(KINDS):
            sid=(mi-1)*6+ki+1
            scenes.append({
                'id':sid,'module':mi,'kind':kind,'durationEstimate':SCENE_DURATIONS[sid-1],
                'label': LABELS[ki].format(n=mi), 'title':m['title'],'concept':m['concept'],'analogy':m['analogy'],
                'rule':m['rule'],'example':m['ex1'],'steps':m['steps'],'example2':m['ex2'],'mistake':m['mistake'],
                'practice':m['practice'],'answer':m['answer'],'narration':narration(kind,m)
            })
    return scenes
